using System.Collections.Immutable;
using DownholeStudio.Core;
using DownholeStudio.Domain;
using DownholeStudio.Synthetics;

namespace DownholeStudio.Cli;

/// <summary>
/// The sample project shipped with the application. Built entirely from synthetic data generated by
/// Downhole Studio (no third-party or customer data), so it can be redistributed freely.
/// </summary>
internal static class SampleProject
{
    public static async Task<string> BuildAsync(string output, AppIdentity identity)
    {
        var options = new SyntheticOptions
        {
            DepthCount = 32, FirstDepth = 1, DepthIncrement = 1, POffset = 2.0, SOffset = 2.0, NoiseLevel = 0.04, TriggerJitter = 0.0006, CommonTriggerDelay = 0.0015,
            PFrequency = 160, SFrequency = 60, Seed = 2026,
        };
        var (session, analysis, survey) = await SyntheticPipeline.BuildAsync(options, "Sample Survey — Synthetic Site", identity, triggerCorrection: true);
        var now = DateTimeOffset.Now;

        session.Execute(Edits.SetMetadata(session.State.Metadata with
        {
            JobNumber = "SAMPLE-001", SurveyDate = new DateOnly(2026, 9, 14), FieldCrew = "Synthetic data — generated by Downhole Studio",
            Description = "A complete worked example: 32 depths, P and opposite-direction S shots, a reference geophone and trigger jitter. All data is synthetic with a known answer.",
            Notes = "True model: 0–3 m Vs 160, 3–8 m Vs 260, 8–15 m Vs 380, 15–24 m Vs 520, below 24 m Vs 760 m/s. True Vs30 ≈ 368 m/s.",
        }));
        var g = session.State.Survey.Geometry;
        session.Execute(Edits.SetGeometry(g with
        {
            Borehole = g.Borehole with { Name = "BH-1", TotalDepth = 33, GroundElevation = 102.4, CoordinateSystem = "Local site grid" },
            PSource = g.PSource with { Description = "30 cm steel plate struck vertically, 4.5 kg hammer" },
            SSource = g.SSource with { Description = "Loaded timber beam struck horizontally at each end (S+ / S−)" },
        }, "Sample geometry"));

        // Arrivals were picked on lightly processed data (mean removal only). A band-pass is then added to the
        // horizontal components to make S arrivals easier to review; picks are not re-run on filtered data,
        // because a zero-phase filter can move energy ahead of a sharp onset.
        session.Execute(Edits.AddStep(session.State, ComponentGroup.Horizontal, new BandPassStep { LowHz = 10, HighHz = 200, Order = 4, ZeroPhase = true }));

        // The analyst reviewed the automatic picks and refined one by hand.
        var stations = session.State.Survey.StationsByDepth();
        session.Execute(Edits.AcceptAutomaticPicks(WaveType.P, [.. stations.Select(s => s.Id)], now));
        session.Execute(Edits.AcceptAutomaticPicks(WaveType.S, [.. stations.Select(s => s.Id)], now));
        var refined = stations.First(s => Math.Abs(s.MeasuredDepth - 12) < 1e-9);
        if (session.State.ActiveScenario.SPicks.TryGetValue(refined.Id, out var p) && p.Time is { } t)
        {
            session.Execute(Edits.SetPick(session.State, WaveType.S, refined.Id, t, p.TraceId, now));
            session.Execute(Edits.SetPickComment(session.State, WaveType.S, refined.Id, "Reviewed on the S+ / S− overlay; onset confirmed."));
        }

        // Layer boundaries placed at the soil changes logged in the boring (here: the synthetic model), as an
        // analyst would; refracted-ray velocities.
        SyntheticPipeline.UseLayers(session, survey.Truth.Layers.Skip(1).Select(l => l.Top), VelocityMethod.RefractedRay);
        string[] labels = ["Fill", "Silty clay", "Medium dense sand", "Dense gravelly sand", "Weathered rock"];
        var interpreted = session.State.ActiveScenario.Layers;
        session.Execute(Edits.SetLayerModel(interpreted with
        {
            Layers = interpreted.Layers.Select((l, i) => l with { Label = labels[Math.Min(i, labels.Length - 1)], Note = "Boundary from the boring log" }).ToImmutableList(),
        }, "Layer labels from the boring log"));

        // Measured densities per layer (from the "site investigation", here the synthetic model).
        var model = session.State.ActiveScenario.Layers;
        var withDensity = model with
        {
            Layers = model.Layers.Select(l =>
            {
                var mid = l.TopDepth + 0.5;
                var truth = survey.Truth.Layers.FirstOrDefault(t => mid >= t.Top && mid < t.Bottom) ?? survey.Truth.Layers[^1];
                return l with { MeasuredDensity = truth.Density };
            }).ToImmutableList(),
        };
        session.Execute(Edits.SetLayerModel(withDensity, "Measured densities from the site investigation", "density.layer"));
        session.Execute(Edits.SetDensityModel(new DensityModel { Source = DensitySource.Measured }));

        session.Execute(Edits.SetReport(session.State.Report with
        {
            Title = "Downhole Seismic Survey — Sample Synthetic Site",
            Client = new ContactInfo { Name = "Example Client (sample data)", Contact = "Project Manager", Address = "100 Example Street, Sample City" },
            Site = new SiteInfo { Name = "Synthetic Test Site", Address = "Not a real location", Description = "Layered soil over weathered rock (synthetic model)." },
            Instrument = new InstrumentInfo
            {
                Seismograph = "24-bit seismograph (synthetic)", BoreholeSensor = "QuakeLogic 3C borehole geophone with reference channel", PSource = "Plate and hammer",
                SSource = "Beam struck at both ends", TriggerType = "Hammer switch",
            },
            Branding = new ReportBranding
            {
                CompanyName = "QuakeLogic Inc.", Website = "quakelogic.net", EngineerName = "Sample Analyst", EngineerTitle = "Geophysicist",
                Footer = "Sample report generated from synthetic data for demonstration purposes.",
            },
            PreparedBy = "Sample Analyst", CheckedBy = "Reviewer",
            ProcessingNotes = "Reference onsets were picked automatically and used to remove 1–2 ms of trigger delay and jitter. P and S arrivals were picked on minimally processed traces (mean removal); a 10–200 Hz zero-phase band-pass was then applied to the horizontal components for review only.",
            Conclusions = "The shear-wave velocity increases from about 160 m/s near the surface to about 760 m/s below 24 m. Vs30 is calculated from measured data to 32 m. This sample project uses synthetic data; the values demonstrate the workflow and are not a site assessment.",
        }));
        session.CreateSnapshot("Reviewed interpretation", "State after reviewing picks and interpreting layers");
        session.Save(output);
        var final = analysis.CalculateNow();
        return $"Sample project written to {output}: {final.LayerResults.Count} layers, Vs30 {final.Vs30.Value:0.0} m/s (true {survey.Truth.Vs30:0.0}), quality {final.Qc.Quality}.";
    }
}
